var import_obsidian8 = require("obsidian");
var TagRenameModal = class extends import_obsidian8.Modal {
  constructor(app, t, tagFormat, onSuccess) {
    super(app);
    this.t = t;
    this.tagFormat = tagFormat;
    this.onSuccess = onSuccess;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.addClass("tag-rename-modal");
    contentEl.createEl("h3", { text: this.t.tagRename.title });
    const oldTagContainer = contentEl.createDiv({
      cls: "tag-rename-input-group"
    });
    oldTagContainer.createEl("label", {
      text: this.t.tagRename.oldTagLabel
    });
    this.oldTagInput = new import_obsidian8.TextComponent(oldTagContainer);
    this.oldTagInput.setPlaceholder(this.t.tagRename.oldTagPlaceholder);
    this.oldTagInput.inputEl.addClass("tag-rename-input");
    const newTagContainer = contentEl.createDiv({
      cls: "tag-rename-input-group"
    });
    newTagContainer.createEl("label", {
      text: this.t.tagRename.newTagLabel
    });
    this.newTagInput = new import_obsidian8.TextComponent(newTagContainer);
    this.newTagInput.setPlaceholder(this.t.tagRename.newTagPlaceholder);
    this.newTagInput.inputEl.addClass("tag-rename-input");
    const buttonContainer = contentEl.createDiv({
      cls: "tag-rename-buttons"
    });
    new import_obsidian8.ButtonComponent(buttonContainer).setButtonText(this.t.modals.cancel).onClick(() => this.close());
    new import_obsidian8.ButtonComponent(buttonContainer).setButtonText(this.t.tagRename.rename).setCta().onClick(() => this.handleRename());
    this.oldTagInput.inputEl.focus();
    this.newTagInput.inputEl.addEventListener("keydown", (e) => {
      if (e.key === "Enter") {
        this.handleRename().catch(
          (error) => console.error("Tag rename failed:", error)
        );
      }
    });
  }
  async handleRename() {
    const oldTag = this.oldTagInput.getValue().trim();
    const newTag = this.newTagInput.getValue().trim();
    if (!oldTag || !newTag) {
      new import_obsidian8.Notice(this.t.tagRename.noTagSpecified);
      return;
    }
    const normalizedOld = oldTag.startsWith("#") ? oldTag.substring(1) : oldTag;
    const normalizedNew = newTag.startsWith("#") ? newTag.substring(1) : newTag;
    if (normalizedOld.toLowerCase() === normalizedNew.toLowerCase()) {
      new import_obsidian8.Notice(this.t.tagRename.sameTagError);
      return;
    }
    new import_obsidian8.Notice(this.t.tagRename.renaming);
    const result = await TagUtils.renameTagInVault(
      this.app,
      normalizedOld,
      normalizedNew,
      void 0,
      this.tagFormat
    );
    if (result.success) {
      new import_obsidian8.Notice(
        this.t.tagRename.success.replace(
          "{count}",
          String(result.affectedFiles)
        )
      );
      this.onSuccess?.();
      this.close();
    } else {
      new import_obsidian8.Notice(result.message);
    }
  }
  onClose() {
    this.contentEl.empty();
  }
};

