// src/utils/tagImportExport.ts
var import_obsidian9 = require("obsidian");
var TagImportExport = class {
  constructor(app) {
    this.app = app;
  }
  // Export all tags from vault to JSON format
  async exportToJSON(files) {
    const entries = await this.collectTagData(files);
    const uniqueTags = /* @__PURE__ */ new Set();
    entries.forEach((e) => e.tags.forEach((t) => uniqueTags.add(t)));
    const data = {
      version: "1.0",
      exportedAt: (/* @__PURE__ */ new Date()).toISOString(),
      totalFiles: entries.length,
      totalTags: uniqueTags.size,
      entries
    };
    return JSON.stringify(data, null, 2);
  }
  // Export all tags from vault to CSV format
  async exportToCSV(files) {
    const entries = await this.collectTagData(files);
    const headers = ["File Path", "Tags"];
    const rows = entries.map((entry) => [
      entry.path,
      entry.tags.join("; ")
    ]);
    const csvContent = [
      headers.join(","),
      ...rows.map(
        (row) => row.map((cell) => `"${cell.replace(/"/g, '""')}"`).join(",")
      )
    ].join("\n");
    return csvContent;
  }
  // Collect tag data from files
  async collectTagData(files) {
    const markdownFiles = files || this.app.vault.getMarkdownFiles();
    const entries = [];
    for (const file of markdownFiles) {
      const cache = this.app.metadataCache.getFileCache(file);
      const tags = cache?.frontmatter ? TagUtils.getExistingTags(cache.frontmatter) : [];
      if (tags.length > 0) {
        entries.push({
          path: file.path,
          tags: tags.map(
            (t) => t.startsWith("#") ? t.substring(1) : t
          )
        });
      }
    }
    return entries.sort((a2, b) => a2.path.localeCompare(b.path));
  }
  // Import tags from JSON
  async importFromJSON(jsonContent, mode, tagFormat) {
    let parsed;
    try {
      parsed = JSON.parse(jsonContent);
    } catch {
      throw new Error("Invalid JSON format");
    }
    if (typeof parsed !== "object" || parsed === null) {
      throw new Error("Invalid tag export format");
    }
    const data = parsed;
    if (!data.entries || !Array.isArray(data.entries)) {
      throw new Error("Invalid tag export format");
    }
    return this.applyTags(data.entries, mode, tagFormat);
  }
  // Import tags from CSV
  async importFromCSV(csvContent, mode, tagFormat) {
    const lines = csvContent.split("\n").filter((l) => l.trim());
    if (lines.length < 2) {
      throw new Error("CSV file is empty or has no data rows");
    }
    const entries = [];
    for (let i = 1; i < lines.length; i++) {
      const parsed = this.parseCSVLine(lines[i]);
      if (parsed.length >= 2) {
        const path = parsed[0];
        const tagsStr = parsed[1];
        const tags = tagsStr.split(/[;,]/).map((t) => t.trim()).filter((t) => t);
        if (path && tags.length > 0) {
          entries.push({ path, tags });
        }
      }
    }
    return this.applyTags(entries, mode, tagFormat);
  }
  // Parse a single CSV line handling quoted fields
  parseCSVLine(line) {
    const result = [];
    let current = "";
    let inQuotes = false;
    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      if (char === '"') {
        if (inQuotes && line[i + 1] === '"') {
          current += '"';
          i++;
        } else {
          inQuotes = !inQuotes;
        }
      } else if (char === "," && !inQuotes) {
        result.push(current);
        current = "";
      } else {
        current += char;
      }
    }
    result.push(current);
    return result;
  }
  // Apply tags to files
  async applyTags(entries, mode, tagFormat) {
    let success = 0;
    let failed = 0;
    let skipped = 0;
    for (const entry of entries) {
      const file = this.app.vault.getAbstractFileByPath(entry.path);
      if (!file || !(file instanceof import_obsidian9.TFile)) {
        skipped++;
        continue;
      }
      try {
        const content = await this.app.vault.read(file);
        const cache = this.app.metadataCache.getFileCache(file);
        let newTags;
        if (mode === "merge") {
          const existingTags = cache?.frontmatter ? TagUtils.getExistingTags(cache.frontmatter) : [];
          const combined = [...existingTags, ...entry.tags];
          newTags = [
            ...new Set(
              combined.map(
                (t) => TagUtils.formatTags(
                  [t],
                  false,
                  tagFormat
                )[0]
              ).filter(Boolean)
            )
          ];
        } else {
          newTags = TagUtils.formatTags(entry.tags, false, tagFormat);
        }
        const frontmatterPosition = cache?.frontmatterPosition;
        let newContent;
        if (frontmatterPosition) {
          const frontmatterText = content.substring(
            frontmatterPosition.start.offset + 4,
            frontmatterPosition.end.offset - 4
          );
          const parsed = (0, import_obsidian9.parseYaml)(frontmatterText) ?? {};
          if (typeof parsed !== "object" || Array.isArray(parsed)) {
            throw new Error("Frontmatter must be a YAML mapping");
          }
          const frontmatter = parsed;
          frontmatter.tags = newTags;
          const newFrontmatter = (0, import_obsidian9.stringifyYaml)(frontmatter).trim();
          newContent = "---\n" + newFrontmatter + "\n---" + content.substring(frontmatterPosition.end.offset);
        } else {
          const frontmatter = { tags: newTags };
          const newFrontmatter = (0, import_obsidian9.stringifyYaml)(frontmatter).trim();
          newContent = "---\n" + newFrontmatter + "\n---\n" + content;
        }
        if (newContent === content) {
          skipped++;
        } else {
          await this.app.vault.modify(file, newContent);
          success++;
        }
      } catch {
        failed++;
      }
    }
    if (success > 0) {
      await new Promise((resolve) => window.setTimeout(resolve, 300));
    }
    return { success, failed, skipped };
  }
  // Download helper for browser
  downloadFile(content, filename, mimeType) {
    const blob = new Blob([content], { type: mimeType });
    const url = URL.createObjectURL(blob);
    const a2 = createEl("a");
    a2.href = url;
    a2.download = filename;
    a2.click();
    URL.revokeObjectURL(url);
  }
};

// src/ui/modals/TagImportModal.ts
var TagImportModal = class extends import_obsidian10.Modal {
  constructor(app, t, tagFormat, onSuccess) {
    super(app);
    this.fileContent = null;
    this.fileType = null;
    this.importMode = "merge";
    this.t = t;
    this.tagFormat = tagFormat;
    this.tagImportExport = new TagImportExport(app);
    this.onSuccess = onSuccess;
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.addClass("tag-import-modal");
    contentEl.createEl("h3", { text: this.t.tagImportExport.importTitle });
    new import_obsidian10.Setting(contentEl).setName(this.t.tagImportExport.selectFile).addButton((btn) => {
      btn.setButtonText(this.t.tagImportExport.selectFile).onClick(() => this.selectFile());
    });
    const fileInfoEl = contentEl.createDiv({ cls: "tag-import-file-info" });
    fileInfoEl.setText("No file selected");
    new import_obsidian10.Setting(contentEl).setName(this.t.tagImportExport.importMode).addDropdown((dropdown) => {
      dropdown.addOption("merge", this.t.tagImportExport.modeMerge).addOption("replace", this.t.tagImportExport.modeReplace).setValue(this.importMode).onChange((value) => {
        this.importMode = value;
      });
    });
    const buttonContainer = contentEl.createDiv({ cls: "tag-import-buttons" });
    new import_obsidian10.ButtonComponent(buttonContainer).setButtonText(this.t.modals.cancel).onClick(() => this.close());
    new import_obsidian10.ButtonComponent(buttonContainer).setButtonText(this.t.tagImportExport.import).setCta().onClick(() => this.handleImport());
  }
  selectFile() {
    const input = createEl("input");
    input.type = "file";
    input.accept = ".json,.csv";
    input.onchange = async (e) => {
      const file = e.target.files?.[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = (event) => {
        this.fileContent = event.target?.result;
        this.fileType = file.name.endsWith(".json") ? "json" : "csv";
        const fileInfoEl = this.contentEl.querySelector(".tag-import-file-info");
        if (fileInfoEl) {
          fileInfoEl.setText(`Selected: ${file.name}`);
        }
      };
      reader.readAsText(file);
    };
    input.click();
  }
  async handleImport() {
    if (!this.fileContent || !this.fileType) {
      new import_obsidian10.Notice(this.t.tagImportExport.noFileSelected);
      return;
    }
    new import_obsidian10.Notice(this.t.tagImportExport.importing);
    try {
      let result;
      if (this.fileType === "json") {
        result = await this.tagImportExport.importFromJSON(
          this.fileContent,
          this.importMode,
          this.tagFormat
        );
      } else {
        result = await this.tagImportExport.importFromCSV(
          this.fileContent,
          this.importMode,
          this.tagFormat
        );
      }
      const message = this.t.tagImportExport.importSuccess.replace("{success}", String(result.success)).replace("{skipped}", String(result.skipped)).replace("{failed}", String(result.failed));
      new import_obsidian10.Notice(message);
      this.onSuccess?.();
      this.close();
    } catch (error) {
      const msg = error instanceof Error ? error.message : "Unknown error";
      new import_obsidian10.Notice(`${this.t.tagImportExport.importError}: ${msg}`);
    }
  }
  onClose() {
    this.contentEl.empty();
  }
};

