// src/ui/modals/TagDeduplicationModal.ts
var TagDeduplicationModal = class extends import_obsidian12.Modal {
  constructor(app, t, tagFormat) {
    super(app);
    this.groups = [];
    this.currentIndex = 0;
    this.t = t;
    this.tagFormat = tagFormat;
    this.deduplicationUtils = new TagDeduplicationUtils(app);
  }
  onOpen() {
    const { contentEl } = this;
    contentEl.empty();
    contentEl.addClass("tag-deduplication-modal");
    contentEl.createEl("h3", { text: this.t.tagDeduplication.title });
    contentEl.createEl("p", {
      text: this.t.tagDeduplication.description,
      cls: "tag-dedup-description"
    });
    const statusEl = contentEl.createDiv({ cls: "tag-dedup-status" });
    statusEl.setText(this.t.tagDeduplication.scanning);
    this.scanAndRender().catch((error) => {
      console.error("Error scanning for duplicate tags:", error);
    });
  }
  async scanAndRender() {
    const { contentEl } = this;
    const statusEl = contentEl.querySelector(
      ".tag-dedup-status"
    );
    this.groups = await this.deduplicationUtils.findSimilarTags();
    if (this.groups.length === 0) {
      statusEl.empty();
      statusEl.addClass("tag-dedup-success");
      statusEl.setText(this.t.tagDeduplication.noDuplicates);
      const closeBtn = contentEl.createEl("button", {
        text: this.t.modals.confirm,
        cls: "mod-cta tag-dedup-close-btn"
      });
      closeBtn.addEventListener("click", () => this.close());
      return;
    }
    statusEl.setText(
      this.t.tagDeduplication.duplicatesFound.replace(
        "{count}",
        String(this.groups.length)
      )
    );
    this.renderCurrentGroup();
  }
  renderCurrentGroup() {
    const existingContent = this.contentEl.querySelector(".tag-dedup-content");
    if (existingContent) existingContent.remove();
    const existingButtons = this.contentEl.querySelector(".tag-dedup-buttons");
    if (existingButtons) existingButtons.remove();
    if (this.currentIndex >= this.groups.length) {
      this.showCompletion();
      return;
    }
    const group = this.groups[this.currentIndex];
    const contentEl = this.contentEl.createDiv({
      cls: "tag-dedup-content"
    });
    const progressEl = contentEl.createDiv({ cls: "tag-dedup-progress" });
    progressEl.setText(`${this.currentIndex + 1} / ${this.groups.length}`);
    const typeEl = contentEl.createDiv({ cls: "tag-dedup-type" });
    typeEl.createSpan({
      text: this.t.tagDeduplication.similarityType + ": "
    });
    typeEl.createSpan({
      text: this.getSimilarityTypeLabel(group.similarityType),
      cls: `tag-dedup-type-badge tag-dedup-type-${group.similarityType}`
    });
    const comparisonEl = contentEl.createDiv({
      cls: "tag-dedup-comparison"
    });
    for (const tagInfo of group.tags) {
      const tagEl = comparisonEl.createDiv({
        cls: `tag-dedup-tag ${tagInfo.tag === group.suggestedTarget ? "is-suggested" : ""}`
      });
      const radioId = `tag-${tagInfo.tag.replace(/[^a-z0-9]/gi, "-")}`;
      const radio = tagEl.createEl("input", {
        type: "radio",
        attr: {
          name: "target-tag",
          id: radioId,
          value: tagInfo.tag
        }
      });
      if (tagInfo.tag === group.suggestedTarget) {
        radio.checked = true;
      }
      const label = tagEl.createEl("label", { attr: { for: radioId } });
      label.createSpan({
        text: `#${tagInfo.tag}`,
        cls: "tag-dedup-tag-name"
      });
      label.createSpan({
        text: this.t.tagDeduplication.usageCount.replace(
          "{count}",
          String(tagInfo.count)
        ),
        cls: "tag-dedup-tag-count"
      });
      if (tagInfo.tag === group.suggestedTarget) {
        label.createSpan({
          text: ` (${this.t.tagDeduplication.keepTag})`,
          cls: "tag-dedup-suggested"
        });
      }
    }
    const buttonsEl = this.contentEl.createDiv({
      cls: "tag-dedup-buttons"
    });
    const skipBtn = buttonsEl.createEl("button", {
      text: this.t.tagDeduplication.skip
    });
    skipBtn.addEventListener("click", () => {
      this.currentIndex++;
      this.renderCurrentGroup();
    });
    const mergeBtn = buttonsEl.createEl("button", {
      text: this.t.tagDeduplication.merge,
      cls: "mod-cta"
    });
    mergeBtn.addEventListener("click", () => {
      this.mergeCurrentGroup().catch(
        (error) => console.error("Tag merge failed:", error)
      );
    });
    if (this.groups.length > 1 && this.currentIndex === 0) {
      const mergeAllBtn = buttonsEl.createEl("button", {
        text: this.t.tagDeduplication.mergeAll,
        cls: "mod-warning"
      });
      mergeAllBtn.addEventListener("click", () => {
        this.mergeAll().catch(
          (error) => console.error("Merge-all failed:", error)
        );
      });
    }
  }
  getSimilarityTypeLabel(type2) {
    switch (type2) {
      case "abbreviation":
        return this.t.tagDeduplication.typeAbbreviation;
      case "case":
        return this.t.tagDeduplication.typeCaseDiff;
      case "plural":
        return this.t.tagDeduplication.typePlural;
      case "similar":
        return this.t.tagDeduplication.typeSimilar;
    }
  }
  async mergeCurrentGroup() {
    const group = this.groups[this.currentIndex];
    const selectedRadio = this.contentEl.querySelector(
      'input[name="target-tag"]:checked'
    );
    const targetTag = selectedRadio?.value || group.suggestedTarget;
    const sourceTags = group.tags.filter((t) => t.tag !== targetTag);
    for (const sourceInfo of sourceTags) {
      const result = await TagUtils.renameTagInVault(
        this.app,
        sourceInfo.tag,
        targetTag,
        void 0,
        this.tagFormat
      );
      if (result.success) {
        const message = this.t.tagDeduplication.mergeSuccess.replace("{source}", sourceInfo.tag).replace("{target}", targetTag).replace("{count}", String(result.affectedFiles));
        new import_obsidian12.Notice(message);
      }
    }
    this.currentIndex++;
    this.renderCurrentGroup();
  }
  async mergeAll() {
    new import_obsidian12.Notice(this.t.tagDeduplication.merging);
    for (let i = this.currentIndex; i < this.groups.length; i++) {
      const group = this.groups[i];
      const targetTag = group.suggestedTarget;
      const sourceTags = group.tags.filter((t) => t.tag !== targetTag);
      for (const sourceInfo of sourceTags) {
        await TagUtils.renameTagInVault(
          this.app,
          sourceInfo.tag,
          targetTag,
          void 0,
          this.tagFormat
        );
      }
    }
    this.currentIndex = this.groups.length;
    this.renderCurrentGroup();
  }
  showCompletion() {
    const existingContent = this.contentEl.querySelector(".tag-dedup-content");
    if (existingContent) existingContent.remove();
    const existingButtons = this.contentEl.querySelector(".tag-dedup-buttons");
    if (existingButtons) existingButtons.remove();
    const statusEl = this.contentEl.querySelector(".tag-dedup-status");
    if (statusEl) {
      statusEl.empty();
      statusEl.addClass("tag-dedup-success");
      statusEl.setText(this.t.tagDeduplication.noDuplicates);
    }
    const closeBtn = this.contentEl.createEl("button", {
      text: this.t.modals.confirm,
      cls: "mod-cta tag-dedup-close-btn"
    });
    closeBtn.addEventListener("click", () => this.close());
  }
  onClose() {
    this.contentEl.empty();
  }
};

// src/commands/utilityCommands.ts
function registerUtilityCommands(plugin) {
  plugin.addCommand({
    id: "collect-all-tags",
    name: plugin.t.commands.collectAllTags,
    icon: "tags",
    callback: async () => {
      await TagUtils.saveAllTags(plugin.app, plugin.settings.tagDir);
    }
  });
  plugin.addCommand({
    id: "show-tag-network",
    name: plugin.t.commands.showTagNetwork,
    icon: "git-graph",
    callback: async () => {
      await plugin.showTagNetwork();
    }
  });
  plugin.addCommand({
    id: "show-tag-analytics",
    name: plugin.t.commands.showTagAnalytics,
    icon: "bar-chart-2",
    callback: async () => {
      await plugin.showTagAnalytics();
    }
  });
  plugin.addCommand({
    id: "bulk-rename-tag",
    name: plugin.t.commands.bulkRenameTag,
    icon: "replace",
    callback: () => {
      new TagRenameModal(
        plugin.app,
        plugin.t,
        plugin.settings.tagFormat
      ).open();
    }
  });
  plugin.addCommand({
    id: "export-tags-csv",
    name: plugin.t.commands.exportTagsCSV,
    icon: "download",
    callback: async () => {
      const exporter = new TagImportExport(plugin.app);
      const csv = await exporter.exportToCSV();
      const filename = `tags-export-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.csv`;
      exporter.downloadFile(csv, filename, "text/csv");
      new import_obsidian13.Notice(plugin.t.tagImportExport.exportSuccess);
    }
  });
  plugin.addCommand({
    id: "export-tags-json",
    name: plugin.t.commands.exportTagsJSON,
    icon: "download",
    callback: async () => {
      const exporter = new TagImportExport(plugin.app);
      const json = await exporter.exportToJSON();
      const filename = `tags-export-${(/* @__PURE__ */ new Date()).toISOString().split("T")[0]}.json`;
      exporter.downloadFile(json, filename, "application/json");
      new import_obsidian13.Notice(plugin.t.tagImportExport.exportSuccess);
    }
  });
  plugin.addCommand({
    id: "import-tags",
    name: plugin.t.commands.importTags,
    icon: "upload",
    callback: () => {
      new TagImportModal(
        plugin.app,
        plugin.t,
        plugin.settings.tagFormat
      ).open();
    }
  });
  plugin.addCommand({
    id: "apply-tag-template",
    name: plugin.t.commands.applyTagTemplate,
    icon: "layout-template",
    callback: () => {
      const activeView = plugin.app.workspace.getActiveViewOfType(import_obsidian13.MarkdownView);
      if (!activeView?.file) {
        new import_obsidian13.Notice(plugin.t.messages.openNote);
        return;
      }
      if (plugin.settings.tagTemplates.length === 0) {
        new import_obsidian13.Notice(plugin.t.tagTemplates.noTemplates);
        return;
      }
      new TagTemplateApplyModal(
        plugin.app,
        plugin.t,
        plugin.settings.tagTemplates,
        activeView.file
      ).open();
    }
  });
  plugin.addCommand({
    id: "deduplicate-tags",
    name: plugin.t.commands.deduplicateTags,
    icon: "git-merge",
    callback: () => {
      new TagDeduplicationModal(
        plugin.app,
        plugin.t,
        plugin.settings.tagFormat
      ).open();
    }
  });
  plugin.addCommand({
    id: "flatten-tags-for-current-note",
    name: plugin.t.commands.flattenTagsForCurrentNote,
    icon: "list-tree",
    callback: async () => {
      const activeView = plugin.app.workspace.getActiveViewOfType(import_obsidian13.MarkdownView);
      if (!activeView?.file) {
        new import_obsidian13.Notice(plugin.t.messages.openNote);
        return;
      }
      const confirmed = await plugin.showConfirmationDialog(plugin.t.messages.flattenTagsConfirm);
      if (!confirmed) {
        new import_obsidian13.Notice(plugin.t.messages.operationCancelled);
        return;
      }
      const result = await TagUtils.flattenHierarchicalTags(
        plugin.app,
        activeView.file,
        plugin.settings.tagFormat
      );
      if (result.success) {
        new import_obsidian13.Notice(result.message);
      } else {
        new import_obsidian13.Notice(`Error: ${result.message}`);
      }
    }
  });
  plugin.addCommand({
    id: "flatten-tags-for-current-folder",
    name: plugin.t.commands.flattenTagsForCurrentFolder,
    icon: "list-tree",
    callback: async () => {
      const activeFile = plugin.app.workspace.getActiveFile();
      if (!activeFile) {
        new import_obsidian13.Notice(plugin.t.messages.openNote);
        return;
      }
      const parentFolder = activeFile.parent;
      if (!parentFolder) {
        new import_obsidian13.Notice(plugin.t.messages.noParentFolder);
        return;
      }
      const filesInFolder = plugin.getNonExcludedMarkdownFilesFromFolder(parentFolder);
      if (filesInFolder.length === 0) {
        new import_obsidian13.Notice(plugin.t.messages.noMdFiles);
        return;
      }
      const confirmed = await plugin.showConfirmationDialog(
        plugin.t.messages.flattenTagsForFolderConfirm.replace("{count}", String(filesInFolder.length))
      );
      if (!confirmed) {
        new import_obsidian13.Notice(plugin.t.messages.operationCancelled);
        return;
      }
      await flattenTagsInFiles(plugin, filesInFolder);
    }
  });
  plugin.addCommand({
    id: "flatten-tags-for-vault",
    name: plugin.t.commands.flattenTagsForVault,
    icon: "list-tree",
    callback: async () => {
      const files = plugin.getNonExcludedMarkdownFiles();
      if (files.length === 0) {
        new import_obsidian13.Notice(plugin.t.messages.noMdFiles);
        return;
      }
      const confirmed = await plugin.showConfirmationDialog(plugin.t.messages.flattenTagsForVaultConfirm);
      if (!confirmed) {
        new import_obsidian13.Notice(plugin.t.messages.operationCancelled);
        return;
      }
      await flattenTagsInFiles(plugin, files);
    }
  });
}
async function flattenTagsInFiles(plugin, files) {
  new import_obsidian13.Notice(plugin.t.messages.flatteningTags);
  let successCount = 0;
  let hasHierarchical = 0;
  for (const file of files) {
    const cache = plugin.app.metadataCache.getFileCache(file);
    const tags = cache?.frontmatter ? TagUtils.getExistingTags(cache.frontmatter) : [];
    if (tags.some((tag) => tag.includes("/"))) {
      hasHierarchical++;
      const result = await TagUtils.flattenHierarchicalTags(
        plugin.app,
        file,
        plugin.settings.tagFormat
      );
      if (result.success) {
        successCount++;
      }
    }
  }
  if (hasHierarchical === 0) {
    new import_obsidian13.Notice(plugin.t.messages.noHierarchicalTags);
  } else {
    new import_obsidian13.Notice(plugin.t.messages.tagsFlattenedSuccessfully.replace("{count}", String(successCount)));
  }
}

