// src/i18n/index.ts
var languageMap = {
  "zh-cn": "\u4E2D\u6587\uFF08\u7B80\u4F53\uFF09",
  "en": "English"
};
var translations = {
  "zh-cn": zhCN,
  "en": en
};
var DEFAULT_LANGUAGE = "en";
function getTranslations(languageCode = DEFAULT_LANGUAGE) {
  return translations[languageCode] || translations[DEFAULT_LANGUAGE];
}
function getLanguageOptions() {
  return Object.entries(languageMap).reduce((acc, [code, name]) => {
    acc[code] = name;
    return acc;
  }, {});
}

